import re
import six
from abc import ABCMeta, abstractmethod

from . import ModelAction
from ..exception import InfoModelObjectNotFoundException, InfoModelObjectParameterNotFoundException


def _extract_location_parts(location):
    return [re.match(r'(?P<part>[^\[,\]]*)(\[(?P<index>.*)\])*', part).groups()[::2] for part in location.split('.')]


def _get_value(names, source):
    if names == []:
        return source
    name, index = names[0]
    try:
        value = source[name][int(index)] if index else source[name]
        return _get_value(names[1:], value)
    except (IndexError, KeyError, TypeError):
        raise InfoModelObjectParameterNotFoundException()


def _create_event_occurence(timestamp, action, dist_name="", data=None):
    data = data or {}
    return {"timestamp": timestamp, "action": action, "dist_name": dist_name, "data": data}


class EventMatcher(object):

    __metaclass__ = ABCMeta

    def __init__(self, description, actions, occurences_matcher):
        self.description = description
        self.actions = actions
        self.occurences_matcher = occurences_matcher
        self.occurences = []

    def match(self, event):
        """Match event."""
        if not event:
            return False
        action, data, timestamp = event
        return self._match_event_data(action, data, timestamp)

    @abstractmethod
    def _match_event_data(self, action, data, timestamp):
        """Base event data matcher method."""

    def satisfied(self):
        """Verify if event occuerence count matches expected count."""
        return self.occurences_matcher(self.get_occurence_count())

    def get_occurence_count(self):
        """Get matching events occuerence count."""
        return len(self.occurences)

    def get_occurences(self):
        """Get occurences list"""
        return self.occurences

    def get_timestamp(self):
        """Get latest occurence timestamp"""
        return self.occurences[-1]["timestamp"] if self.occurences else None

    def clear_occurences(self):
        """Clear occurences list"""
        del self.occurences[:]

    def set_infomodel_state(self, im_dump):
        """Set initial InfoModel state"""
        pass

    def __str__(self):
        return self.description

    def __repr__(self):
        return "%s: %s" % (self.__class__, self.description)


class BasicEventMatcher(EventMatcher):

    def _match_event_data(self, action, data, timestamp):
        if action in self.actions:
            self.occurences.append(_create_event_occurence(timestamp, action))
            return True
        else:
            return False


class RemoveEventMatcher(EventMatcher):

    def __init__(self, description, occurences_matcher, dist_name_regex):
        EventMatcher.__init__(self, description, [ModelAction.ON_REMOVE], occurences_matcher)
        self.dist_name_regex = dist_name_regex

    def _match_event_data(self, action, data, timestamp):
        result = False
        if action in self.actions:
            for dist_name in data:
                if re.match(self.dist_name_regex, dist_name):
                    self.occurences.append(_create_event_occurence(timestamp, action, dist_name))
                    result = True
        return result


class ExtendedEventMatcher(EventMatcher):

    def __init__(self, description, actions, occurences_matcher, dist_name_regex, predicate=None):
        EventMatcher.__init__(self, description, actions, occurences_matcher)
        self.traced_objects = {}
        self.dist_name_regex = dist_name_regex

        if predicate:
            self.predicate = True
            self.parameter = _extract_location_parts(predicate[0])
            self.first_value_matcher = predicate[1]
            self.second_value_matcher = predicate[2]
        else:
            self.predicate = False

        self.action_handlers = {
            ModelAction.ON_RESET: self._match_reset,
            ModelAction.ON_REMOVE: self._match_remove,
            ModelAction.ON_UPDATE: self._match_update,
        }

    def set_infomodel_state(self, im_dump):
        """Set initial InfoModel state"""
        self._match_update(im_dump, "init")
        self.clear_occurences()

    def _match_event_data(self, action, data, timestamp):
        return self.action_handlers[action](data, timestamp)

    def _match_reset(self, data, timestamp):
        self.traced_objects.clear()
        if ModelAction.ON_RESET in self.actions:
            self.occurences.append(_create_event_occurence(timestamp, ModelAction.ON_RESET))
            return True
        return False

    def _match_remove(self, removed, timestamp):
        result = False
        for dist_name in removed:
            if re.match(self.dist_name_regex, dist_name):
                if ModelAction.ON_REMOVE in self.actions and self._match_object_remove(dist_name):
                    self.occurences.append(_create_event_occurence(timestamp, ModelAction.ON_REMOVE, dist_name))
                    result = True
                self._remove_traced_obeject(dist_name)
        return result

    def _match_object_remove(self, dist_name):
        if not self.predicate:
            return True
        try:
            value = self._get_and_update_traced_object(dist_name)
            return self.first_value_matcher(value)
        except InfoModelObjectNotFoundException:
            return False

    def _remove_traced_obeject(self, dist_name):
        if dist_name in self.traced_objects:
            del self.traced_objects[dist_name]

    def _match_update(self, updated, timestamp):
        result = False
        for dist_name, updated_params in six.iteritems(updated):
            if re.match(self.dist_name_regex, dist_name) and self._match_object_update(dist_name, updated_params):
                if ModelAction.ON_UPDATE in self.actions:
                    self.occurences.append(_create_event_occurence(timestamp, ModelAction.ON_UPDATE, dist_name, updated_params))
                    result = True
        return result

    def _match_object_update(self, dist_name, changed_params):
        if self.predicate:
            return self._match_object_update_with_predicate(dist_name, changed_params)
        else:
            return self._match_object_update_without_predicate(dist_name)

    def _match_object_update_with_predicate(self, dist_name, changed_params):
        try:
            new_value = _get_value(self.parameter, changed_params)
            previous_value = self._get_and_update_traced_object(dist_name, new_value)
            return previous_value != new_value and self.first_value_matcher(previous_value) and self.second_value_matcher(new_value)
        except (TypeError, InfoModelObjectNotFoundException, InfoModelObjectParameterNotFoundException):
            return False

    def _match_object_update_without_predicate(self, dist_name):
        try:
            self._get_and_update_traced_object(dist_name)
        except InfoModelObjectNotFoundException:
            return False
        else:
            return True

    def _get_and_update_traced_object(self, dist_name, new_value=None):
        try:
            return self.traced_objects[dist_name]
        except KeyError:
            return self._handle_uninitialized_traced_object()
        finally:
            self.traced_objects[dist_name] = new_value

    @abstractmethod
    def _handle_uninitialized_traced_object(self):
        """Base"""


class ExtendedRemoveMatcher(ExtendedEventMatcher):

    def __init__(self, description, occurences_matcher, dist_name_regex, predicate):
        ExtendedEventMatcher.__init__(self, description, [ModelAction.ON_REMOVE], occurences_matcher, dist_name_regex, predicate)

    def _handle_uninitialized_traced_object(self):
        raise InfoModelObjectNotFoundException


class CreateEventMatcher(ExtendedEventMatcher):

    def __init__(self, description, occurences_matcher, dist_name_regex, predicate):
        ExtendedEventMatcher.__init__(self, description, [ModelAction.ON_UPDATE], occurences_matcher, dist_name_regex, predicate)

    def _handle_uninitialized_traced_object(self):
        raise InfoModelObjectNotFoundException

    def _match_object_update_with_predicate(self, dist_name, changed_params):
        try:
            new_value = _get_value(self.parameter, changed_params)
            self._get_and_update_traced_object(dist_name, new_value)
        except InfoModelObjectNotFoundException:
            return self.first_value_matcher(new_value)
        except InfoModelObjectParameterNotFoundException:
            return False
        else:
            return False

    def _match_object_update_without_predicate(self, dist_name):
        try:
            self._get_and_update_traced_object(dist_name)
        except InfoModelObjectNotFoundException:
            return True
        else:
            return False


class ChangeEventMatcher(ExtendedEventMatcher):

    def __init__(self, description, occurences_matcher, dist_name_regex, predicate):
        ExtendedEventMatcher.__init__(self, description, [ModelAction.ON_UPDATE], occurences_matcher, dist_name_regex, predicate)

    def _handle_uninitialized_traced_object(self):
        raise InfoModelObjectNotFoundException


class UpdateEventMatcher(ExtendedEventMatcher):

    def __init__(self, description, occurences_matcher, dist_name_regex, predicate):
        actions = [ModelAction.ON_UPDATE]
        if not predicate:
            actions.extend([ModelAction.ON_RESET, ModelAction.ON_REMOVE])
        ExtendedEventMatcher.__init__(self, description, actions, occurences_matcher, dist_name_regex, predicate)

    def _handle_uninitialized_traced_object(self):
        return None


class SequenceMatcher(object):

    def __init__(self, event_matchers):
        self.index = 0
        self.event_matchers = event_matchers

    def match(self, event):
        """Match event."""
        if self.satisfied():
            return False

        result = self.event_matchers[self.index].match(event)

        for event_matcher in self.event_matchers[self.index + 1:]:
            event_matcher.match(event)

        while not self.satisfied() and self.event_matchers[self.index].satisfied():
            self.index += 1

        for event_matcher in self.event_matchers[self.index + 1:]:
            event_matcher.clear_occurences()

        return result

    def satisfied(self):
        """Verify if event occuerence count matches expected count."""
        return self.index >= len(self.event_matchers)

    def get_occurences(self):
        """Get occurences list"""
        occurences = []
        for event_matcher in self.event_matchers:
            occurences.extend(event_matcher.get_occurences())
        return occurences

    def get_occurence_count(self):
        """Get matching events occuerence count."""
        occurence_count = 0
        for event_matcher in self.event_matchers:
            occurence_count += event_matcher.get_occurence_count()
        return occurence_count

    def clear_occurences(self):
        """Clear occurences list"""
        self.index = 0
        for event_matcher in self.event_matchers:
            event_matcher.clear_occurences()

    def set_infomodel_state(self, im_dump):
        """Set initial InfoModel state"""
        for event_matcher in self.event_matchers:
            event_matcher.set_infomodel_state(im_dump)

    def __str__(self):
        return "sequence\n" + "\n".join([str(event_matcher) for event_matcher in self.event_matchers])
